  bottom: -30%;
  left: -10%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(21,41,90,0.4) 0%, transparent 70%);
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 800px;
}

.hero-label {
  display: inline-block;
  padding: 6px 16px;
  background: rgba(0,180,216,0.1);
  border: 1px solid rgba(0,180,216,0.25);
  border-radius: 100px;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--teal);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 24px;
}

.hero h1 {
  font-size: 3.8rem;
  font-weight: 900;
  line-height: 1.1;
  color: var(--white);
  letter-spacing: -0.03em;
  margin-bottom: 24px;
}

.hero h1 span {
  background: linear-gradient(135deg, var(--teal), var(--blue-bright));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero h2 {
  font-size: 1.15rem;
  font-weight: 400;
  color: var(--gray-400);
  line-height: 1.7;
  max-width: 600px;
  margin-bottom: 40px;
}

.hero-buttons {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 32px;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  transition: all var(--transition);
  cursor: pointer;
  border: none;
  font-family: inherit;
}

.btn-primary {
  background: var(--teal);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--blue-bright);
  box-shadow: 0 0 28px rgba(0,180,216,0.35);
  transform: translateY(-1px);
}

.btn-secondary {
  background: transparent;
  color: var(--white);
  border: 1.5px solid rgba(255,255,255,0.2);
}

.btn-secondary:hover {
  border-color: var(--white);
  background: rgba(255,255,255,0.04);
}

.btn-outline-teal {
  background: transparent;
  color: var(--teal);
  border: 1.5px solid var(--teal);
}

.btn-outline-teal:hover {
  background: var(--teal);
  color: var(--white);
}

/* ===== Section Common ===== */
.section {
  padding: 100px 0;
  position: relative;
}

.section-label {
  display: inline-block;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--teal);
  text-transform: uppercase;
  letter-spacing: 0.12em;
  margin-bottom: 16px;
}

.section-title {
  font-size: 2.6rem;
  font-weight: 800;
  color: var(--white);
  letter-spacing: -0.02em;
  line-height: 1.2;
  margin-bottom: 20px;
}

.section-subtitle {
  font-size: 1.05rem;
  color: var(--gray-400);
  max-width: 640px;
  line-height: 1.7;
  margin-bottom: 48px;
}

/* ===== Featured Product Banner ===== */
.featured-banner {
  background: linear-gradient(135deg, var(--navy) 0%, var(--charcoal) 100%);
  border: 1px solid rgba(0,180,216,0.12);
  border-radius: var(--radius-lg);
  padding: 48px 56px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
  position: relative;
  overflow: hidden;
  margin: 0 32px;
}

.featured-banner::before {
  content: '';
  position: absolute;
  right: -5%;
  top: -40%;
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, rgba(0,180,216,0.1) 0%, transparent 70%);
  pointer-events: none;
}

.featured-banner-content h3 {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--teal);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 8px;
}

.featured-banner-content h2 {
  font-size: 2rem;
  font-weight: 800;
  color: var(--white);
  margin-bottom: 4px;
}

.featured-banner .btn {
  flex-shrink: 0;
  position: relative;
  z-index: 1;
}

/* ===== Tabs ===== */
.tabs-nav {
  display: flex;
  gap: 4px;
  background: var(--charcoal);
  border-radius: var(--radius-md);
  padding: 5px;
  margin-bottom: 40px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.tabs-nav-btn {
  padding: 12px 24px;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--gray-400);
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all var(--transition);
  font-family: inherit;
  white-space: nowrap;
}

.tabs-nav-btn.active {
  background: var(--teal);
  color: var(--white);
}

.tabs-nav-btn:hover:not(.active) {
  color: var(--white);
  background: rgba(255,255,255,0.04);
}

.tab-panel {
  display: none;
}

.tab-panel.active {
  display: block;
  animation: fadeIn 0.4s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ===== Use Cases Grid ===== */
.use-cases-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.use-case-card {
  background: var(--charcoal);
  border: 1px solid rgba(255,255,255,0.05);
  border-radius: var(--radius-lg);
  padding: 36px 32px;
  transition: all var(--transition);
  cursor: pointer;
}

.use-case-card:hover {
  border-color: rgba(0,180,216,0.25);
  transform: translateY(-4px);
  box-shadow: var(--shadow-glow);
}

.use-case-card-icon {
  width: 48px;
  height: 48px;
  background: rgba(0,180,216,0.1);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  color: var(--teal);
  font-size: 1.3rem;
}

.use-case-card h3 {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 10px;
}

.use-case-card p {
  font-size: 0.9rem;
  color: var(--gray-400);
  line-height: 1.6;
}

/* ===== Ecosystem Diagram ===== */
.ecosystem-diagram {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 48px;
  padding: 20px 0;
  flex-wrap: wrap;
}

.ecosystem-pillar {
  text-align: center;
  flex: 1;
  min-width: 240px;
  max-width: 340px;
}

.ecosystem-pillar-inner {
  background: var(--charcoal);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 40px 28px;
  transition: all var(--transition);
  height: 100%;
}

.ecosystem-pillar-inner:hover {
  border-color: rgba(0,180,216,0.2);
  box-shadow: var(--shadow-glow);
}

.ecosystem-icon-circle {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: rgba(0,180,216,0.08);
  border: 2px solid rgba(0,180,216,0.2);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 24px;
  font-size: 1.8rem;
  color: var(--teal);
}

.ecosystem-pillar-inner h3 {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 12px;
}

.ecosystem-pillar-inner p {
  font-size: 0.9rem;
  color: var(--gray-400);
  line-height: 1.6;
}

.ecosystem-connector {
  display: flex;
  align-items: center;
  color: var(--teal);
  font-size: 1.5rem;
  opacity: 0.5;
}

/* ===== Cards ===== */
.card {
  background: var(--charcoal);
  border: 1px solid rgba(255,255,255,0.05);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition);
}

.card:hover {
  border-color: rgba(0,180,216,0.15);
}

/* ===== Benefits Section ===== */
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.benefit-card {
  background: var(--charcoal);
  border: 1px solid rgba(255,255,255,0.05);
  border-radius: var(--radius-lg);
  padding: 36px 32px;
  transition: all var(--transition);
}

.benefit-card:hover {
  border-color: rgba(0,180,216,0.2);
  transform: translateY(-3px);
  box-shadow: var(--shadow-glow);
}

.benefit-card-icon {
  width: 52px;
  height: 52px;
  background: rgba(108,194,74,0.1);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  color: var(--green);
  font-size: 1.3rem;
}

.benefit-card h3 {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 10px;
}

.benefit-card p {
  font-size: 0.9rem;
  color: var(--gray-400);
  line-height: 1.6;
}

/* ===== Stats Circles ===== */
.stats-row {
  display: flex;
  justify-content: center;
  gap: 80px;
  flex-wrap: wrap;
}

.stat-circle {
  text-align: center;
}

.stat-circle-outer {
  width: 160px;
  height: 160px;
  border-radius: 50%;
  background: conic-gradient(var(--teal) 0deg, var(--teal) calc(var(--pct) * 3.6deg), var(--charcoal) calc(var(--pct) * 3.6deg));
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
  position: relative;
}

.stat-circle-outer::before {
  content: '';
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: var(--charcoal);
  position: absolute;
}

.stat-circle-value {
  position: relative;
  z-index: 1;
  font-size: 2rem;
  font-weight: 900;
  color: var(--white);
}

.stat-circle-label {
  font-size: 0.9rem;
  color: var(--gray-400);
  max-width: 180px;
  line-height: 1.5;
}

/* ===== Timeline ===== */
.timeline {
  max-width: 800px;
  margin: 0 auto;
}

.timeline-item {
  display: flex;
  gap: 24px;
  align-items: flex-start;
  margin-bottom: 32px;
}

.timeline-marker {
  flex-shrink: 0;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--charcoal);
  border: 2px solid var(--teal);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 0.85rem;
  color: var(--teal);
}

.timeline-content {
  flex: 1;
}

.timeline-content h3 {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 6px;
}

.timeline-content p {
  font-size: 0.9rem;
  color: var(--gray-400);
  margin-bottom: 12px;
}

.timeline-bar {
  height: 6px;
  background: var(--charcoal-light);
  border-radius: 3px;
  overflow: hidden;
}

.timeline-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--teal), var(--blue-bright));
  border-radius: 3px;
  transition: width 1s ease;
}

/* ===== Accordion ===== */
.accordion-item {
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-md);
  margin-bottom: 12px;
  overflow: hidden;
  background: var(--charcoal);
}

.accordion-header {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 22px 28px;
  background: none;
  border: none;
  color: var(--white);
  font-size: 1.05rem;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  text-align: left;
  transition: background var(--transition);
}

.accordion-header:hover {
  background: rgba(255,255,255,0.02);
}

.accordion-icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: rgba(0,180,216,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform var(--transition);
  flex-shrink: 0;
  color: var(--teal);
  font-size: 1.1rem;
}

.accordion-item.open .accordion-icon {
  transform: rotate(45deg);
  background: var(--teal);
  color: var(--white);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease;
}

.accordion-item.open .accordion-body {
  max-height: 300px;
}

.accordion-body-inner {
  padding: 0 28px 24px;
  font-size: 0.95rem;
  color: var(--gray-300);
  line-height: 1.7;
}

/* ===== Testimonials Carousel ===== */
.testimonials-carousel {
  position: relative;
  overflow: hidden;
}

.testimonials-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.testimonial-slide {
  min-width: 100%;
  padding: 0 12px;
}

.testimonial-card {
  background: var(--charcoal);
  border: 1px solid rgba(255,255,255,0.05);
  border-radius: var(--radius-lg);
  padding: 40px 36px;
  text-align: center;
}

.testimonial-card .quote-mark {
  font-size: 3rem;
  color: var(--teal);
  opacity: 0.3;
  line-height: 1;
  margin-bottom: 16px;
}

.testimonial-card blockquote {
  font-size: 1.1rem;
  color: var(--gray-200);
  line-height: 1.7;
  font-style: italic;
  margin-bottom: 20px;
}

.testimonial-card .attribution {
  font-size: 0.88rem;
  color: var(--teal);
  font-weight: 600;
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 32px;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--slate);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
  padding: 0;
}

.carousel-dot.active {
  background: var(--teal);
  box-shadow: 0 0 10px rgba(0,180,216,0.4);
}

/* ===== Data Lifecycle Diagram ===== */
.lifecycle-diagram {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
  padding: 20px 0;
}

.lifecycle-step {
  text-align: center;
  flex: 1;
  min-width: 140px;
}

.lifecycle-step-circle {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: var(--charcoal);
  border: 2px solid rgba(0,180,216,0.3);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 14px;
  font-size: 1.5rem;
  color: var(--teal);
  transition: all var(--transition);
}

.lifecycle-step:hover .lifecycle-step-circle {
  border-color: var(--teal);
  box-shadow: 0 0 24px rgba(0,180,216,0.2);
  transform: scale(1.05);
}

.lifecycle-step h4 {
  font-size: 0.9rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 4px;
}

.lifecycle-step p {
  font-size: 0.78rem;
  color: var(--gray-400);
}

.lifecycle-arrow {
  color: var(--teal);
  font-size: 1.2rem;
  opacity: 0.4;
  flex-shrink: 0;
}

/* ===== Security Features ===== */
.security-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.security-card {
  background: var(--charcoal);
  border: 1px solid rgba(255,255,255,0.05);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition);
}

.security-card:hover {
  border-color: rgba(0,180,216,0.2);
}

.security-card-icon {
  width: 44px;
  height: 44px;
  background: rgba(0,180,216,0.1);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  color: var(--teal);
  font-size: 1.2rem;
}

.security-card h3 {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 10px;
}

.security-card p {
  font-size: 0.9rem;
  color: var(--gray-400);
  line-height: 1.6;
}

/* ===== ETL Benefits (checkmark list) ===== */
.etl-benefits-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}

.etl-benefit-item {
  display: flex;
  gap: 16px;
  align-items: flex-start;
  background: var(--charcoal);
  border: 1px solid rgba(255,255,255,0.05);
  border-radius: var(--radius-md);
  padding: 24px;
}

.etl-benefit-check {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(108,194,74,0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--green);
  flex-shrink: 0;
  font-size: 1rem;
  font-weight: 700;
}

.etl-benefit-item h3 {
  font-size: 1rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 6px;
}

.etl-benefit-item p {
  font-size: 0.88rem;
  color: var(--gray-400);
  line-height: 1.6;
}

/* ===== CTA Sections ===== */
.cta-section {
  background: linear-gradient(135deg, var(--navy) 0%, var(--charcoal) 100%);
  border: 1px solid rgba(0,180,216,0.1);
  border-radius: var(--radius-xl);
  padding: 56px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-section::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, rgba(0,180,216,0.06) 0%, transparent 70%);
  pointer-events: none;
}

.cta-section h2 {
  font-size: 2.2rem;
  font-weight: 800;
  color: var(--white);
  margin-bottom: 16px;
  position: relative;
}

.cta-section p {
  font-size: 1.05rem;
  color: var(--gray-400);
  max-width: 600px;
  margin: 0 auto 32px;
  position: relative;
  line-height: 1.7;
}

/* ===== Form ===== */
.form-container {
  max-width: 720px;
  margin: 0 auto;
  background: var(--charcoal);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-xl);
  padding: 52px 48px;
}

.form-row {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
  margin-bottom: 20px;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.form-group.full {
  grid-column: 1 / -1;
}

.form-group label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--gray-300);
}

.form-group label .required {
  color: var(--teal);
}

.form-group input,
.form-group select,
.form-group textarea {
  padding: 12px 16px;
  background: var(--navy-deep);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-sm);
  color: var(--white);
  font-size: 0.95rem;
  font-family: inherit;
  transition: border-color var(--transition);
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--teal);
  box-shadow: 0 0 0 3px rgba(0,180,216,0.1);
}

.form-group input.error,
.form-group select.error,
.form-group textarea.error {
  border-color: #ef4444;
}

.form-error {
  font-size: 0.8rem;
  color: #ef4444;
  display: none;
}

.form-error.visible {
  display: block;
}

.form-group textarea {
  resize: vertical;
  min-height: 100px;
}

.form-submit-row {
  margin-top: 32px;
}

.form-submit-row .btn {
  width: 100%;
  justify-content: center;
  padding: 16px;
  font-size: 1rem;
}

.form-success {
  display: none;
  text-align: center;
  padding: 60px 40px;
}

.form-success.visible {
  display: block;
  animation: fadeIn 0.5s ease;
}

.form-success-icon {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: rgba(108,194,74,0.12);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 24px;
  font-size: 2rem;
  color: var(--green);
}

.form-success h2 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 12px;
}

.form-success p {
  color: var(--gray-400);
}

/* ===== Support Contact ===== */
.support-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.support-card {
  background: var(--charcoal);
  border: 1px solid rgba(255,255,255,0.05);
  border-radius: var(--radius-lg);
  padding: 32px;
  text-align: center;
  transition: all var(--transition);
}

.support-card:hover {
  border-color: rgba(0,180,216,0.2);
}

.support-card-icon {
  font-size: 2rem;
  color: var(--teal);
  margin-bottom: 16px;
}

.support-card h3 {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 8px;
}

.support-card p {
  font-size: 0.9rem;
  color: var(--gray-400);
  line-height: 1.6;
}

/* ===== Company Culture ===== */
.culture-split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.culture-visual {
  background: var(--charcoal);
  border-radius: var(--radius-xl);
  padding: 48px;
  text-align: center;
  border: 1px solid rgba(255,255,255,0.05);
  position: relative;
  overflow: hidden;
  min-height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.culture-visual-inner {
  position: relative;
  z-index: 1;
}

.culture-visual-icon {
  font-size: 4rem;
  color: var(--teal);
  opacity: 0.6;
  margin-bottom: 16px;
}

.culture-visual h3 {
  font-size: 1.3rem;
  color: var(--white);
  font-weight: 700;
}

.culture-visual::before {
  content: '';
  position: absolute;
  top: -20%;
  right: -20%;
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, rgba(0,180,216,0.08) 0%, transparent 70%);
  pointer-events: none;
}

.culture-stats {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
  margin-top: 32px;
}

.culture-stat {
  background: rgba(255,255,255,0.03);
  border-radius: var(--radius-md);
  padding: 20px;
  text-align: center;
}

.culture-stat-value {
  font-size: 1.8rem;
  font-weight: 800;
  color: var(--teal);
}

.culture-stat-label {
  font-size: 0.82rem;
  color: var(--gray-400);
  margin-top: 4px;
}

/* ===== Footer ===== */
.footer {
  background: var(--charcoal);
  border-top: 1px solid rgba(255,255,255,0.05);
  padding: 72px 0 40px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand h3 {
  font-size: 1.3rem;
  font-weight: 800;
  color: var(--white);
  margin-bottom: 12px;
}

.footer-brand h3 span {
  color: var(--teal);
}

.footer-brand p {
  font-size: 0.9rem;
  color: var(--gray-400);
  line-height: 1.6;
  max-width: 300px;
}

.footer-col h4 {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--white);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 20px;
}

.footer-col a {
  display: block;
  font-size: 0.9rem;
  color: var(--gray-400);
  padding: 5px 0;
  transition: color var(--transition);
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 32px;
  border-top: 1px solid rgba(255,255,255,0.06);
  font-size: 0.85rem;
  color: var(--gray-500);
}

.footer-bottom-links {
  display: flex;
  gap: 24px;
}

.footer-bottom-links a {
  color: var(--gray-500);
  transition: color var(--transition);
}

.footer-bottom-links a:hover {
  color: var(--gray-300);
}

/* ===== Cookie Banner ===== */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 999;
  background: var(--charcoal);
  border-top: 1px solid rgba(255,255,255,0.08);
  padding: 20px 0;
  box-shadow: 0 -4px 24px rgba(0,0,0,0.4);
  transform: translateY(100%);
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.cookie-banner.visible {
  transform: translateY(0);
}

.cookie-banner.hidden {
  display: none;
}

.cookie-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 32px;
}

.cookie-text {
  font-size: 0.9rem;
  color: var(--gray-300);
  line-height: 1.6;
}

.cookie-text a {
  color: var(--teal);
  text-decoration: underline;
}

.cookie-buttons {
  display: flex;
  gap: 12px;
  flex-shrink: 0;
}

.cookie-btn {
  padding: 10px 24px;
  font-size: 0.88rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  cursor: pointer;
  border: none;
  font-family: inherit;
  transition: all var(--transition);
}

.cookie-btn-accept {
  background: var(--teal);
  color: var(--white);
}

.cookie-btn-accept:hover {
  background: var(--blue-bright);
}

.cookie-btn-decline {
  background: transparent;
  color: var(--gray-400);
  border: 1px solid rgba(255,255,255,0.15);
}

.cookie-btn-decline:hover {
  color: var(--white);
  border-color: rgba(255,255,255,0.3);
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .hero h1 { font-size: 2.8rem; }
  .section-title { font-size: 2.1rem; }
  .use-cases-grid { grid-template-columns: repeat(2, 1fr); }
  .benefits-grid { grid-template-columns: repeat(2, 1fr); }
  .security-grid { grid-template-columns: repeat(2, 1fr); }
  .etl-benefits-list { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr 1fr; }
  .culture-split { grid-template-columns: 1fr; gap: 40px; }
  .stats-row { gap: 48px; }
  .ecosystem-diagram { gap: 24px; }
  .ecosystem-connector { display: none; }
  .lifecycle-diagram { gap: 8px; }
  .lifecycle-arrow { display: none; }
  .support-grid { grid-template-columns: repeat(2, 1fr); }
  .featured-banner { margin: 0 16px; flex-direction: column; text-align: center; }
}

@media (max-width: 768px) {
  .container { padding: 0 20px; }
  .nav-inner { padding: 0 20px; }

  .nav-links {
    position: fixed;
    top: 72px;
    left: 0;
    right: 0;
    background: var(--charcoal);
    flex-direction: column;
    padding: 24px;
    gap: 8px;
    border-bottom: 1px solid rgba(255,255,255,0.06);
    transform: translateY(-100%);
    opacity: 0;
    visibility: hidden;
    transition: all var(--transition);
    align-items: stretch;
  }

  .nav-links.mobile-open {
    transform: translateY(0);
    opacity: 1;
    visibility: visible;
  }

  .nav-mobile-toggle { display: flex; }

  .nav-link, .nav-dropdown-toggle {
    padding: 12px 0;
    font-size: 1rem;
  }

  .nav-dropdown-menu {
    position: static;
    background: transparent;
    border: none;
    box-shadow: none;
    padding: 0 0 0 16px;
    opacity: 1;
    visibility: visible;
    transform: none;
    display: none;
  }

  .nav-dropdown.open .nav-dropdown-menu {
    display: block;
  }

  .nav-cta {
    margin-top: 12px;
    justify-content: center;
  }

  .hero { padding: 120px 0 80px; }
  .hero h1 { font-size: 2.2rem; }
  .hero h2 { font-size: 1rem; }
  .hero-buttons { flex-direction: column; }
  .hero-buttons .btn { width: 100%; justify-content: center; }

  .section { padding: 64px 0; }
  .section-title { font-size: 1.8rem; }

  .use-cases-grid { grid-template-columns: 1fr; }
  .benefits-grid { grid-template-columns: 1fr; }
  .security-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: 32px; }
  .stats-row { gap: 32px; }
  .stat-circle-outer { width: 130px; height: 130px; }
  .stat-circle-outer::before { width: 96px; height: 96px; }
  .stat-circle-value { font-size: 1.5rem; }

  .ecosystem-diagram { flex-direction: column; align-items: stretch; }
  .ecosystem-pillar { max-width: none; }
  .lifecycle-diagram { flex-direction: column; align-items: center; gap: 8px; }
  .lifecycle-step { min-width: auto; width: 100%; display: flex; align-items: center; gap: 16px; text-align: left; }
  .lifecycle-step-circle { margin: 0; width: 52px; height: 52px; font-size: 1.2rem; }

  .form-row { grid-template-columns: 1fr; }
  .form-container { padding: 32px 24px; }
  .cta-section { padding: 40px 24px; }
  .cta-section h2 { font-size: 1.6rem; }

  .support-grid { grid-template-columns: 1fr; }
  .cookie-inner { flex-direction: column; text-align: center; }
  .cookie-buttons { width: 100%; justify-content: center; }
  .footer-bottom { flex-direction: column; gap: 12px; text-align: center; }

  .featured-banner { margin: 0 8px; padding: 32px 24px; }
  .featured-banner-content h2 { font-size: 1.4rem; }

  .tabs-nav { gap: 2px; padding: 4px; }
  .tabs-nav-btn { padding: 10px 16px; font-size: 0.82rem; }

  .culture-stats { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 480px) {
  .hero h1 { font-size: 1.8rem; }
  .section-title { font-size: 1.5rem; }
  .stat-circle-outer { width: 110px; height: 110px; }
  .stat-circle-outer::before { width: 82px; height: 82px; }
  .stat-circle-value { font-size: 1.3rem; }
  .timeline-item { flex-direction: column; gap: 12px; align-items: center; text-align: center; }
  .timeline-content { text-align: center; }
}
